code_snippets.parse_list:
def parse_list(self, response):
    items = response.css('ul li')
    for item in items:
        detail_url = item.css('a::attr(href)').get()
        if detail_url and detail_url.startswith('/home/'):
            yield response.follow(detail_url, self.parse_detail)

code_snippets.parse_detail:
def parse_detail(self, response):
    title = response.css('h1.page-title::text').get()
    description = response.css('div.study-description::text').get()
    pdf_urls = response.css('a[href$=".pdf"]::attr(href)').getall()
    yield {
        'title': title.strip() if title else None,
        'description': description.strip() if description else None,
        'pdf_urls': [response.urljoin(url) for url in pdf_urls]
    }
